questions.model:
def first_at_least(sorted_nums, x):
    lo, hi = 0, len(sorted_nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if sorted_nums[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo
